-- template: Architectural Design Phase (Pre-Execution)
update public.quote_templates set note = '<h2>SPACE WORK SARL – Proposal / Agreement (FACADE Implementation Drawings Assistance)</h2><p><strong>SPACE WORK SARL</strong> (hereinafter referred to as “SPACEWORK”), a company duly registered under the laws of Lebanon, with its principal place of business located in Beirut, specializing in façade consulting, engineering, and design.</p><h3>1. Scope of Work</h3><p>SPACEWORK agrees to provide the following services to the Client for the project (the “Project”):</p><h4 class="rt-in1">1.1. Review &amp; Alignment (Concept Confirmation)</h4><p class="rt-in2">a. Review the existing façade conceptual design package issued by others (architect/client).</p><p class="rt-in2">b. Confirm façade intent, system direction, and key constraints (interfaces, performance targets, typical details).</p><p class="rt-in2">c. Issue a brief list of clarifications / RFIs required to proceed.</p><h4 class="rt-in1">1.2. Façade Implementation / Tender-Level Drawings (Not Shop Drawings)</h4><p class="rt-in2">SPACEWORK will develop façade <strong>implementation drawings</strong> intended for coordination and tendering, including (as applicable):</p><p class="rt-in2">a. General Arrangement façade elevations and typical zones.</p><p class="rt-in2">b. Typical sections/details at key junctions (slab edge, parapet, head/sill/jamb, corner, movement joints, interfaces with waterproofing, etc.).</p><p class="rt-in2">c. Typical anchoring intent and load-path concept (indicative only).</p><p class="rt-in2">d. Interface coordination notes with structure, architecture, and MEP penetrations (as required).</p><p class="rt-in2">e. Material/system intent notes suitable for tender coordination.</p><h4 class="rt-in1">1.3. Technical Assistance &amp; Coordination</h4><p class="rt-in2">a. Periodic design coordination meetings (remote) and written responses to Client queries.</p><p class="rt-in2">b. One round of tender clarification support based on submitted implementation package.</p><h4 class="rt-in1">1.4. Explicit Exclusions </h4><p class="rt-in2">Unless agreed by written amendment, the following are <strong>excluded</strong>:</p><p class="rt-in2">a. Shop drawings, fabrication drawings, assembly drawings, and installation method statements.</p><p class="rt-in2">b. Full structural calculations, stamping, or third-party authority submissions.</p><p class="rt-in2">c. Detailed cutting lists, CNC files, or optimization schedules.</p><p class="rt-in2">d. Full procurement support, supplier nomination, or tender evaluation (unless added).</p><p class="rt-in2">e. Site supervision / inspections / as-built drawings.</p><h3 class="rt-in1">2. Deliverables</h3><p class="rt-in2">2.1. <strong>Façade Implementation Drawing Set</strong> (tender/coordination level, not shop drawings), including typical elevations/sections/details and key interfaces.</p><p class="rt-in2">2.2. <strong>Implementation Notes</strong> (if needed) summarizing system intent, interfaces, and assumptions.</p><p class="rt-in2">2.3. <strong>RFI / Clarification Log</strong> (if needed) documenting missing inputs and decisions required.</p><h3 class="rt-in1">3. Responsibilities of the Client</h3><p class="rt-in2">3.1. Provide SPACEWORK with all relevant project information, including architectural/structural drawings, conceptual façade package, project schedule, and design 		requirements.</p><p class="rt-in2">3.2. Provide timely decisions, approvals, and consolidated feedback.</p><p class="rt-in2">3.3. Appoint a single point of contact authorized to confirm decisions.</p><p class="rt-in2">3.4. Ensure all third-party design inputs (architect/structural/MEP) are coordinated and issued in current revision.</p><h3 class="rt-in1">4. Timeline</h3><p class="rt-in2">4.1. SPACEWORK will issue deliverables within a mutually agreed timeframe starting from receipt of complete project information and formal appointment.</p><p class="rt-in2">4.2. Delays caused by missing information, late approvals, or late feedback will result in corresponding extensions to the timeline and may result in additional fees if 		the delay exceeds <strong>thirty (30) calendar days</strong>.</p><h2 class="rt-in1">5. Fees and Payment Terms</h2><p class="rt-in2">5.1. The total fee for the services under this Agreement is <strong>a lump sum price mentioned in the B.O.Q</strong>, payable in <strong>USD cash</strong> or <strong>USD fresh bank transfer</strong>, exclusive of applicable taxes and bank transfer charges.</p><p class="rt-in2">5.2. Payment milestones are as follows:</p><p class="rt-in3">a. <strong>40%</strong> upon signing this Agreement </p><p class="rt-in3">b. <strong>40%</strong> upon submission of the <strong>first implementation drawing package</strong> (GA + typical details)</p><p class="rt-in3">c. <strong>20%</strong> upon submission of the <strong>final implementation drawing package</strong> incorporating agreed comments </p><p class="rt-in2">5.3. Payments must be made within <strong>15 days</strong> of receiving an invoice. Any delay in payment will cause a direct delay to project delivery.</p><h3 class="rt-in1">5.4. Submittal and Review Procedure</h3><p class="rt-in2">a. SPACEWORK shall submit deliverables to the Client based on the milestones above (or every <strong>28 days</strong> if the program requires phased submissions).</p><p class="rt-in2">b. The Client is entitled to <strong>two (2) review cycles</strong> per submission, each review period not exceeding <strong>seven (7) days</strong>.</p><p class="rt-in2">c. In case of rejection, SPACEWORK shall revise and resubmit within <strong>fourteen (14) days</strong>, subject to timely receipt of consolidated comments.</p><p class="rt-in2">d. If the Client fails to provide feedback within <strong>seven (7) days</strong> of submission, the submission shall be deemed approved for invoicing purposes, and SPACEWORK shall be entitled to invoice for the completed milestone.</p><p class="rt-in2">e. Requests that constitute <strong>scope expansion</strong> (e.g., moving to shop drawing/fabrication level, extensive redesign, additional façade areas/zones not included in the concept) may be repriced by SPACEWORK based on the original pricing structure and level of effort.</p><h2 class="rt-in1">6. Intellectual Property</h2><p class="rt-in2">6.1. All designs, drawings, and documents provided by SPACEWORK remain its intellectual property until full payment is received.</p><p class="rt-in2">6.2. Upon full payment, the Client receives a non-exclusive license to use the deliverables solely for the Project.</p><p class="rt-in2">6.3. SPACEWORK retains the right to use non-confidential visuals for portfolio and promotional purposes.</p><h2 class="rt-in1">7. Confidentiality</h2><p class="rt-in2">7.1. Both parties agree to keep all project-related information confidential and not disclose it to any third party without prior written consent, except as required by law.</p><h2 class="rt-in1">8. Liability and Warranty</h2><p class="rt-in2">8.1. SPACEWORK will perform its services with professional care and diligence.</p><p class="rt-in2">8.2. SPACEWORK is not liable for delays or costs arising from factors beyond its control, including Client-provided information or third-party dependencies.</p><p class="rt-in2">8.3. The Client acknowledges that the deliverables are <strong>implementation/tender-level</strong> and may require further detailing and development by a façade contractor/specialist during execution and shop drawing stages.</p><h2 class="rt-in1">9. Termination</h2><p class="rt-in2">9.1. Either party may terminate this Agreement only by mutual written agreement.</p><p class="rt-in2">9.2. Upon termination, the Client will compensate SPACEWORK for all work completed up to the termination date.</p><h2 class="rt-in1">10. Dispute Resolution</h2><p class="rt-in2">10.1. Any disputes arising from this Agreement will be resolved amicably through negotiations.</p><p class="rt-in2">10.2. If negotiations fail, disputes will be subject to arbitration under the Rules of Conciliation and Arbitration at the Beirut Chamber of Commerce and Industry by three (3) arbitrators appointed in accordance with said rules.</p><h2 class="rt-in1">11. Governing Law</h2><p class="rt-in2">This Agreement is governed by the laws of Lebanon.</p><h2 class="rt-in1">12. Entire Agreement</h2><p class="rt-in2">This Agreement constitutes the entire understanding between the parties and supersedes all prior agreements, understandings, or representations.</p><h2 class="rt-in1">13. Amendments</h2><p class="rt-in2">This Agreement may only be amended in writing and signed by both parties.</p><p><br></p><p><strong>IN WITNESS WHEREOF</strong>, the parties have executed this Agreement as of the date first written above.</p><p>For <strong>SPACEWORK SARL</strong></p><p><strong>Kevin J. Gemayel</strong></p><p>Managing Director</p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and name = 'Architectural Design Phase (Pre-Execution)';

-- @chunk

-- template: Facade Execution Supervision (Construction Phase)
update public.quote_templates set note = '<h4>1. Scope of Work </h4><p>SPACEWORK agrees to provide the following services to the Client for the project (the “Project”):</p><p>1.1. Review &amp; Alignment (Pre-Execution Confirmation)</p><p class="rt-in1">a. Review the approved façade design intent package (architect/client/consultant) and contractor’s method statements / ITPs (if available).</p><p class="rt-in1">b. Confirm façade intent, system direction, key interfaces, performance targets, and critical risk points prior to execution.</p><p class="rt-in1">c. Issue a brief list of clarifications / RFIs required to proceed with execution.</p><p>1.2. Site Supervision &amp; Quality Control (Façade Works)</p><p>SPACEWORK will provide supervision and technical support during façade execution, including (as applicable):</p><p class="rt-in1">a. Periodic site visits to monitor façade installation progress and workmanship quality.</p><p class="rt-in1">b. Verification of critical installation stages (anchors/brackets, waterproofing interfaces, glazing setting, movement joints, sealant works, etc.).</p><p class="rt-in1">c. Review of contractor submissions relevant to execution (method statements, material submittals, mockup/test plans) <strong>at a supervision level</strong>.</p><p class="rt-in1">d. Snagging / punch-list issuance for façade works and follow-up on closures.</p><p class="rt-in1">e. Technical advice to resolve site issues and conflicts, without redesigning the approved concept unless instructed.</p><p>1.3. Meetings &amp; Reporting</p><p class="rt-in1">a. Attendance of periodic coordination meetings (remote or on-site as agreed on a monthly basis).</p><p class="rt-in1">b. Issuance of site visit reports after each visit, highlighting observations, non-conformities, action items, and recommendations.</p><p>1.4. Explicit Exclusions</p><p>Unless agreed by written amendment, the following are excluded:</p><p class="rt-in1">a. Full-time resident supervision (24/7 presence) unless specifically stated.</p><p class="rt-in1">b. Shop drawings, fabrication drawings, cutting lists, CNC files, optimization schedules.</p><p class="rt-in1">c. Structural calculations, design stamping, authority submissions.</p><p class="rt-in1">d. Procurement, supplier nomination, commercial tender evaluation, contract administration under FIDIC (unless added).</p><p class="rt-in1">e. Laboratory testing services (unless added), and third-party inspection certifications.</p><p class="rt-in1">f. As-built drawings (unless added).</p><p class="rt-in1">g. Responsibility for contractor means/methods, safety, scaffolding, lifting plans, and site HSE compliance.</p><h4>2. Deliverables</h4><p>2.1. <strong>Site Visit Reports</strong> (after each visit) with photos (if permitted), observations, NCR notes (if needed), and action items.</p><p><strong>2.2. Façade Snag / Punch List (periodic and/or at substantial completion) and closure tracking.</strong></p><p><strong>2.3. RFI / Clarification Log (if needed)</strong> documenting technical queries and agreed resolutions.</p><p>2.4. <strong>Close-Out Note</strong> confirming façade completion status from a supervision standpoint (optional, if required).</p><h4>3. Responsibilities of the Client</h4><p>3.1. Provide SPACEWORK with all relevant project details and updated drawings, site schedule, contractor program, and façade contractor contact details.</p><p>3.2. Ensure SPACEWORK receives timely access to site, scaffolding/working platforms, and safe access arrangements by the contractor.</p><p>3.3. Ensure timely communication, decisions, and consolidated feedback to facilitate smooth execution.</p><p>3.4. Appoint a single point of contact authorized to confirm decisions and coordinate visits.</p><p>3.5. Ensure the contractor implements corrective actions and provides responses to observations within agreed timeframes.</p><h4>4. Timeline</h4><p>4.1. SPACEWORK services shall commence upon formal appointment and receipt of required project information, and shall continue for the agreed supervision duration.</p><p>4.2. Delays due to site access limitations, lack of information, or suspension of works may result in schedule adjustments. If works are suspended for more than <strong>thirty (30) calendar days</strong>, SPACEWORK reserves the right to reprice or remobilize based on remaining scope.</p><h4>5. Fees and Payment Terms </h4><p>5.1. The total fee for the services under this Agreement is a lump sum price mentioned in the B.O.Q, payable in <strong>USD cash</strong> or <strong>USD fresh bank transfer</strong>, exclusive of applicable taxes and bank transfer charges.</p><p class="rt-in1">a. <strong>30%</strong> upon signing this Agreement (mobilization).</p><p class="rt-in1">b. <strong>30%</strong> upon completion of the first 30–40% of façade installation (or first major elevation/zone).</p><p class="rt-in1">c. <strong>30%</strong> upon substantial completion of façade installation.</p><p class="rt-in1">d. <strong>10%</strong> upon final snag closure and close-out report.</p><p>5.3. Payments &amp; Delays</p><p>Payments must be made within <strong>15 days</strong> of receiving an invoice. Any delay in payment may result in suspension of supervision services and corresponding delay to the Project.</p><p>5.4. Site Visit Regime </p><p>SPACEWORK supervision includes maximum of 2 site visits per month.</p><p>Additional visits beyond the agreed number shall be charged at <strong>USD 500 / visit</strong>.</p><p>5.5. Reporting and Response Procedure</p><p class="rt-in1">a. SPACEWORK shall issue a report within <strong>48–72 hours</strong> after each site visit.</p><p class="rt-in1">b. The Client/Contractor shall respond to observations within <strong>seven (7) days</strong>, confirming corrective actions and timelines.</p><p class="rt-in1">c. Repeated non-compliance or scope escalation may require repricing based on effort and frequency of visits.</p><h4>6. Intellectual Property</h4><p>6.1. All documents and reports provided by SPACEWORK remain its intellectual property until full payment is received.</p><p>6.2. Upon full payment, the Client receives a non-exclusive license to use the deliverables solely for the Project.</p><p>6.3. SPACEWORK retains the right to use non-confidential visuals for portfolio and promotional purposes.</p><h4>7. Confidentiality</h4><p>7.1. Both parties agree to keep all project-related information confidential and not disclose it to any third party without prior written consent, except as required by law.</p><h4>8. Liability and Warranty (Adjusted for Supervision)</h4><p>8.1. SPACEWORK will perform its services with professional care and diligence.</p><p>8.2. SPACEWORK is not responsible for the contractor’s workmanship, means and methods, site safety, sequencing, or compliance with HSE requirements.</p><p>8.3. SPACEWORK supervision is advisory/observational and does not relieve the contractor of its obligations to execute works in accordance with contract documents and applicable standards.</p><p>8.4. SPACEWORK is not liable for delays or costs arising from factors beyond its control, including Client-provided information, contractor performance, or third-party dependencies.</p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and name = 'Facade Execution Supervision (Construction Phase)';

