-- S00018
update public.sale_orders set narration = '<h2>1. PARTIES</h2><h3>1.1 Main Contractor</h3><p><strong>ALGECO LTD</strong></p><h3>1.2 Subcontractor</h3><p><strong>SPACE WORK  SARL </strong></p><p>(hereinafter referred to as <strong>“SPACE WORK”</strong> or the <strong>“Subcontractor”</strong>)</p><p>ALGECO and SPACE WORK may each be referred to as a <strong>“Party”</strong> and collectively as the <strong>“Parties.”</strong></p><p>This Agreement governs the subcontracted works related to the <strong>installation of Aluminum Composite Panels (ACP) on the building façade</strong> for the above-mentioned project.</p><h2>3. SCOPE OF WORK</h2><p>SPACE WORK shall provide all labor, supervision, tools, small equipment, consumables, and site execution resources necessary to complete the ACP installation works in accordance with the project requirements, including but not limited to:</p><h2>4. CONTRACT DOCUMENTS (ORDER OF PRECEDENCE)</h2><p>This Agreement shall be read together with the following documents (collectively, the <strong>“Contract Documents”</strong>):</p><ol><li><p>This Subcontract Agreement</p></li><li><p>Scope of Work / BOQ / Commercial Offer (Annex A)</p></li><li><p>Approved drawings and details (Annex B)</p></li></ol><p>In case of conflict, the order of precedence above shall apply unless otherwise agreed in writing.</p><h2>5. CONTRACT PRICE</h2><ul><li><p>If VAT is applicable, it shall be added to the certified amount at the prevailing legal rate and against valid tax invoice.</p></li></ul><h2>6. PAYMENT TERMS</h2><h3>6.1 Payment Schedule (Recommended)</h3><p>Payments shall be made by ALGECO to SPACE WORK as follows:</p><p><strong>Option A – Progress Payment Basis (Most common):</strong></p><ul><li><p><strong>[80]%</strong> Advance payment upon signing (against advance guarantee, if required)</p></li><li><p><strong>[10]%</strong> Monthly progress payments based on approved installed quantities and certification</p></li><li><p><strong>[10]%</strong> Retention</p></li></ul><p><strong>Option B – No Advance:</strong></p><ul><li><p>Monthly progress payments based on approved installed quantities and certification</p></li><li><p>Retention applied as stated below</p></li></ul><h3>6.2 Monthly Progress Claims</h3><p>SPACE WORK shall submit monthly progress invoices/claims with supporting documents, including:</p><ul><li><p>Measured installed quantities</p></li><li><p>Site progress sheets signed by ALGECO representative</p></li><li><p>Photos / progress report (if requested)</p></li><li><p>Any required QA/QC records</p></li></ul><p>ALGECO shall review and certify the payable amount within <strong>[7–14] calendar days</strong> from receipt of complete documentation.</p><h3>6.3 Payment Due Date</h3><p>Certified amounts shall be paid within <strong>[30] calendar days</strong> from:</p><ul><li><p>receipt of valid invoice by ALGECO, and</p></li><li><p>certification of the work done, and</p></li><li><p>receipt of payment by ALGECO from the Client (if “pay-when-paid” applies and is enforceable under applicable law).</p></li></ul><blockquote><p><strong>Note (optional clause):</strong> Payment by ALGECO to SPACE WORK is subject to ALGECO receiving corresponding payment from the Client for the relevant executed works (“pay-when-paid”), to the extent permitted by applicable law.</p></blockquote><h3>6.4 Deductions</h3><p>ALGECO may deduct from amounts due to SPACE WORK any documented and justified costs arising from:</p><ul><li><p>Rework due to defective installation by SPACE WORK</p></li><li><p>Damage caused by SPACE WORK personnel</p></li><li><p>Back charges for safety violations (if contractually established and documented)</p></li><li><p>Approved penalties/liquidated damages attributable solely to SPACE WORK (if expressly agreed)</p></li></ul><h2>7. TIME FOR COMPLETION AND PROGRAM</h2><h3>7.1 Commencement</h3><p>SPACE WORK shall commence the works within <strong>[30] days</strong> from receipt of:</p><ul><li><p>written notice to proceed from ALGECO,</p></li><li><p>access to work fronts,</p></li><li><p>approved drawings relevant to the area, and</p></li><li><p>required materials delivered to the work area (if supply is by ALGECO).</p></li></ul><h3>7.2 Completion Period</h3><p>SPACE WORK shall complete its subcontract works within <strong>[30] calendar days / weeks</strong> in accordance with the project schedule and sequencing plan issued by ALGECO.</p><h3>7.3 Work Sequence</h3><p>SPACE WORK shall perform the works in accordance with ALGECO’s site instructions and project sequencing, including phased handovers and priority areas.</p><h3>7.4 Delays / EOT</h3><p>SPACE WORK shall be entitled to reasonable extension of time (without cost unless expressly agreed) for delays caused by:</p><ul><li><p>Late release of drawings</p></li><li><p>Lack of access / obstruction by others</p></li><li><p>Delay in material supply by ALGECO or others</p></li><li><p>Variations instructed by ALGECO</p></li><li><p>Force majeure events</p></li><li><p>Suspension by ALGECO not caused by SPACE WORK default</p></li></ul><p>Any delay event must be notified in writing within <strong>[2–5] days</strong> of occurrence.</p><h2>8. RESPONSIBILITIES OF ALGECO (CONTRACTOR)</h2><p>ALGECO shall:</p><p>a. Provide access to work fronts as per agreed schedule.</p><p>b. Provide approved drawings/details and instructions for execution.</p><p>c. Coordinate site interfaces with other trades.</p><p><br></p><h2>9. RESPONSIBILITIES OF SPACE WORK (SUBCONTRACTOR)</h2><p>SPACE WORK shall:</p><p>a. Execute the works in a professional and workmanlike manner in accordance with approved drawings, specifications, and good industry practice.</p><p>b. Provide qualified supervisors, foremen, and installers experienced in ACP façade installation.</p><h3>10. Handover on Termination</h3><p>Upon termination, SPACE WORK shall vacate the site in an orderly manner, hand over completed works, and submit final measurement and claim for executed works.</p><p><br></p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and number = 'S00018';

-- @chunk

-- S00016
update public.sale_orders set narration = '<p><strong>SPACE WORK SARL</strong> (hereinafter referred to as “SPACE WORK”), a company duly registered under the laws of Lebanon, with its principal place of business located at Beirut, specializing in façade consulting, engineering, and design.</p><p><br></p><p><strong>1. Scope of Work</strong> </p><p>SPACEWORK agrees to provide the following services to the Client: </p><p>1.1. Structural Calculation Note for:</p><p class="rt-in1">1.1.1 Tubular Louvers and Typical Curtainwall for Entrance Block</p><p><br></p><p><br></p><p><strong>3. Responsibilities of the Client</strong> </p><p>3.1. Provide SPACEWORK with all relevant project details, including architectural plans, project scope, timelines, and specific requirements.</p><p>3.2. Ensure timely communication and feedback to facilitate smooth project execution. </p><p>3.3. Obtain necessary approvals and permits for project execution, if required.</p><p><strong>4. Timeline</strong> </p><p>4.1. SPACE WORK will provide the agreed deliverables within specified time frame from the date of receiving all necessary project information from the Client. </p><p>4.2. Delays caused by the Client’s failure to provide required information or feedback will result in corresponding adjustments to the timeline, and may result in additional charges if the delay exceeds thirty calendar days.</p><p><strong>5. Fees and Payment Terms</strong> </p><p>5.1. The total fee for the services provided under this Agreement is mentioned above and should be settled in U.S.D Cash or USD Fresh Bank Transfer, exclusive of applicable taxes and transfer fees. </p><p>5.2. Payment milestones are as follows: </p><p class="rt-in1">a. 80% upon signing this Agreement. </p><p class="rt-in1">b. 10% upon first submission of works</p><p class="rt-in1">c. 10% upon receiving approval</p><p>5.3. Payments must be made within 7 days of receiving an invoice, and payment delay will cause a direct delay to the project delivery.</p><p>5.4 Submittals Procedures:</p><p class="rt-in1">SPACE WORK shall prepare and submit deliverables to the Client for approval every 28 days, aligning with the specified milestones.</p><p class="rt-in1">The Client is entitled to review each submission up to two times, with each review period not exceeding seven (7) days. In case of rejection, SPACE WORK shall revise and resubmit within fourteen (14) days.</p><p class="rt-in1">If the Client fails to provide feedback within seven (7) days; failure to respond within (7) days submission shall be deemed approved, and SPACE WORK shall be entitled to invoice for the completed work.</p><p class="rt-in1">SPACE WORK reserves the right to reprice the work, within reasonable limits, based on the original contract pricing structure, should substantial revisions be required beyond the agreed-upon scope.</p><p><br></p><p><strong>5. Intellectual Property</strong> </p><p>6.1. All designs, drawings, and specifications provided by SPACEWORK remain its intellectual property until full payment is received. </p><p>6.2. Upon full payment, the Client receives a non-exclusive license to use the deliverables solely for the specified project. </p><p>6.3. SPACEWORK retains the right to use the designs for promotional and portfolio purposes.</p><p><br></p><p><strong>7. Confidentiality</strong> </p><p>7.1. Both parties agree to keep all project-related information confidential and not disclose it to any third party without prior written consent, except as required by law.</p><p><br></p><p><strong>8. Liability and Warranty</strong> </p><p>8.1. SPACEWORK will perform its services with professional care and diligence. </p><p>8.2. SPACEWORK is not liable for any project delays or costs arising from factors beyond its control, including Client-provided information or third-party dependencies. </p><p>8.3. The Client acknowledges that the deliverables are conceptual and may require further detailing and adjustment by third parties during execution.</p><p><br></p><p><strong>9. Termination</strong> </p><p>9.1. Either party may not terminate this Agreement, unless agreed by both parties. </p><p>9.2. Upon termination, the Client will compensate SPACEWORK for all work completed up to the termination date.</p><p><br></p><p><strong>10. Dispute Resolution</strong> </p><p>10.1. Any disputes arising from this Agreement will be resolved amicably through negotiations. </p><p>10.2. If negotiations fail, disputes will be subject to arbitration under the Rules of Conciliation and Arbitration at the Beirut Chamber of Commerce and Industry by three (3) Arbitrators appointed in accordance with the said rules. The said arbitrators shall have full power to open up, review and revise any decision, opinion, instruction, determination, certificate or valuation of the Engineer related to the dispute.</p><p><br></p><p><strong>11. Governing Law</strong> </p><p>This Agreement is governed by the laws of Lebanon.</p><p><br></p><p><strong>12. Entire Agreement</strong> </p><p>This Agreement constitutes the entire understanding between the parties and supersedes all prior agreements, understandings, or representations.</p><p><br></p><p><strong>13. Amendments</strong> </p><p>This Agreement may only be amended in writing and signed by both parties.</p><p><br></p><p><strong>IN WITNESS WHEREOF</strong>, the parties have executed this Agreement as of the date first written above.</p><p><br></p><p><strong>For SPACEWORK SARL</strong></p><p><br></p><p><strong>Kevin J. Gemayel</strong></p><p><em>Managing Director</em><br></p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and number = 'S00016';

-- @chunk

