-- S00011
update public.sale_orders set narration = '<p><strong>SPACE WORK SARL</strong> (hereinafter referred to as “SPACE WORK”), a company duly registered under the laws of Lebanon, with its principal place of business located at Beirut, specializing in façade consulting, engineering, and design.</p><p><br></p><p><strong>1. Scope of Work</strong> </p><p>SPACEWORK agrees to provide the following services to the Client: </p><p>1.1. Structural Calculation Note for:</p><p class="rt-in1">1.1.1 One Type of Fixed Louver</p><p class="rt-in1">1.1.2 One type of Sliding Louver</p><p><br></p><p><strong>3. Responsibilities of the Client</strong> </p><p>3.1. Provide SPACEWORK with all relevant project details, including architectural plans, project scope, timelines, and specific requirements.</p><p>3.2. Ensure timely communication and feedback to facilitate smooth project execution. </p><p>3.3. Obtain necessary approvals and permits for project execution, if required.</p><p><strong>4. Timeline</strong> </p><p>4.1. SPACE WORK will provide the agreed deliverables within specified time frame from the date of receiving all necessary project information from the Client. </p><p>4.2. Delays caused by the Client’s failure to provide required information or feedback will result in corresponding adjustments to the timeline, and may result in additional charges if the delay exceeds thirty calendar days.</p><p><strong>5. Fees and Payment Terms</strong> </p><p>5.1. The total fee for the services provided under this Agreement is mentioned above and should be settled in U.S.D Cash or USD Fresh Bank Transfer, exclusive of applicable taxes and transfer fees. </p><p>5.2. Payment milestones are as follows: </p><p class="rt-in1">a. 80% upon quotation approval</p><p class="rt-in1">b. 20% upon receiving approval</p><p>5.3. Payments must be made within 7 days of receiving an invoice, and payment delay will cause a direct delay to the project delivery.</p><p>5.4 Submittals Procedures:</p><p class="rt-in1">SPACE WORK shall prepare and submit deliverables to the Client for approval every 28 days, aligning with the specified milestones.</p><p class="rt-in1">The Client is entitled to review each submission up to two times, with each review period not exceeding seven (7) days. In case of rejection, SPACE WORK shall revise and resubmit within fourteen (14) days.</p><p class="rt-in1">If the Client fails to provide feedback within seven (7) days; failure to respond within (7) days submission shall be deemed approved, and SPACE WORK shall be entitled to invoice for the completed work.</p><p class="rt-in1">SPACE WORK reserves the right to reprice the work, within reasonable limits, based on the original contract pricing structure, should substantial revisions be required beyond the agreed-upon scope.</p><p><br></p><p><strong>5. Intellectual Property</strong> </p><p>6.1. All designs, drawings, and specifications provided by SPACEWORK remain its intellectual property until full payment is received. </p><p>6.2. Upon full payment, the Client receives a non-exclusive license to use the deliverables solely for the specified project. </p><p>6.3. SPACEWORK retains the right to use the designs for promotional and portfolio purposes.</p><p><br></p><p><strong>7. Confidentiality</strong> </p><p>7.1. Both parties agree to keep all project-related information confidential and not disclose it to any third party without prior written consent, except as required by law.</p><p><br></p><p><strong>8. Liability and Warranty</strong> </p><p>8.1. SPACEWORK will perform its services with professional care and diligence. </p><p>8.2. SPACEWORK is not liable for any project delays or costs arising from factors beyond its control, including Client-provided information or third-party dependencies. </p><p>8.3. The Client acknowledges that the deliverables are conceptual and may require further detailing and adjustment by third parties during execution.</p><p><br></p><p><strong>9. Termination</strong> </p><p>9.1. Either party may not terminate this Agreement, unless agreed by both parties. </p><p>9.2. Upon termination, the Client will compensate SPACEWORK for all work completed up to the termination date.</p><p><br></p><p><strong>10. Dispute Resolution</strong> </p><p>10.1. Any disputes arising from this Agreement will be resolved amicably through negotiations. </p><p>10.2. If negotiations fail, disputes will be subject to arbitration under the Rules of Conciliation and Arbitration at the Beirut Chamber of Commerce and Industry by three (3) Arbitrators appointed in accordance with the said rules. The said arbitrators shall have full power to open up, review and revise any decision, opinion, instruction, determination, certificate or valuation of the Engineer related to the dispute.</p><p><br></p><p><strong>11. Governing Law</strong> </p><p>This Agreement is governed by the laws of Lebanon.</p><p><br></p><p><strong>12. Entire Agreement</strong> </p><p>This Agreement constitutes the entire understanding between the parties and supersedes all prior agreements, understandings, or representations.</p><p><br></p><p><strong>13. Amendments</strong> </p><p>This Agreement may only be amended in writing and signed by both parties.</p><p><br></p><p><strong>IN WITNESS WHEREOF</strong>, the parties have executed this Agreement as of the date first written above.</p><p><br></p><p><strong>For SPACEWORK SARL</strong></p><p><br></p><p><strong>Kevin J. Gemayel</strong></p><p><em>Managing Director</em><br></p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and number = 'S00011';

-- @chunk

-- S00007
update public.sale_orders set narration = '<p><strong>SPACEWORK SARL</strong> (hereinafter referred to as “SPACEWORK”), a company duly registered under the laws of Lebanon, with its principal place of business located at Beirut, specializing in façade consulting, engineering, and design; </p><p><strong>1. Scope of Work</strong> </p><p>SPACEWORK agrees to provide the following services to the Client: </p><p>1.1. Façade Technical and Engineering design, submittals up to 6 revision, limited to the BOQ items attached, including and limited to : </p><p class="rt-in1">a. Façade concept drawings, Consulting and engineering services related to façade design.</p><p class="rt-in1">b. Shop Drawings </p><p class="rt-in1">c. Method Statments</p><p class="rt-in1">d. Calculation Notes and Reports</p><p class="rt-in1">e. Coordination meeting with Client and Consultant to ensure all approvals</p><p><strong>2. Deliverables</strong> </p><p>2.1. Complete set of approed Shop Drawings</p><p>2.2. Complete set of calculation Notes</p><p>2.3 Complete set of Material and Method statments</p><p>2.4 Engineering submittal log</p><p><strong>3. Responsibilities of the Client</strong> </p><p>3.1. Provide SPACEWORK with all relevant project details, including architectural plans, project scope, timelines, and specific requirements, and all complete works.</p><p>3.2. Ensure timely communication and feedback to facilitate smooth project execution. </p><p><strong>4. Exclusions</strong></p><p>If any of the below scopes are needed they will discussed at a later stage in a different contract. </p><p>4.1. Fabrication Drawings, Fabrication quality control, Fabrication Quantity Control, Cutting Lists, Assembly Drawings</p><p>4.2. Project Management responsibilites related to budget, schedules, quality and quantity control, procurement, logistics, resource managment.</p><p>4.3. Site Engineeting responsibilites related to Site measurments, surveying, site managments, construciton control, inventory management.</p><p><strong>5. Timeline</strong> </p><p>5.1. SPACEWORK will provide the agreed deliverables within 3 months if the client replies to submittals within 1 calendar week, any holidays or delyed replies will directly affect the scope completion date, the start will be considered upon receiving all necessary project information from the Client, and down payment is received. </p><p>5.2. Delays caused by the Client’s failure to provide required information or feedback will result in corresponding adjustments to the timeline, and may result in additional charges if the delay exceeds thirty calendar days.</p><p><strong>6. Fees and Payment Terms</strong> </p><p>6.1. The total fee for the services provided under this Agreement is mentioned above and should be settled in U.S.D Cash or USD Fresh Bank Transfer, exclusive of applicable taxes and transfer fees. </p><p>6.2. Payment milestones are as follows: </p><p class="rt-in1">a. 25% upon signing this Agreement. (must be paid if full)</p><p class="rt-in1">b. 25% upon submission of Typical Details and Basis of design. (can be gradually invoiced, based on progress reports)</p><p class="rt-in1">c. 20% upon submission of Shop Drawings (can be gradually invoiced, based on progress reports)</p><p class="rt-in1">d. 20% upon submission of Calculation notes and Method Statements. (can be gradually invoiced, based on progress reports)</p><p class="rt-in1">e. 10% Remaining balance upon receiving approvals. </p><p>6.3. Payments must be made within 15 days of receiving an invoice, and payment delay will cause a direct delay to the project delivery.</p><p>6.4 Submittals Procedures:</p><p><br></p><p class="rt-in1">SPACE WORK shall prepare and submit deliverables to the Client for approval every 14 days, aligning with the specified milestones.</p><p class="rt-in1">The Client is entitled to review each submission up to six times, with each review period not exceeding seven (7) days. In case of rejection, SPACE WORK shall revise and resubmit within fourteen (14) days.</p><p class="rt-in1">If the Client fails to provide feedback within seven (7) days; failure to respond within (7) days submission shall be deemed approved, and SPACE WORK shall be entitled to invoice for the related works.</p><p class="rt-in1">SPACE WORK reserves the right to reprice the work, within reasonable limits, based on the original contract pricing structure, should substantial revisions be required beyond the agreed-upon scope.</p><p><strong>7. Intellectual Property</strong> </p><p>7.1. All designs, drawings, and specifications provided by SPACEWORK remain its intellectual property until full payment is received. </p><p>7.2. Upon full payment, the Client receives a non-exclusive license to use the deliverables solely for the specified project. </p><p>7.3. SPACEWORK retains the right to use the designs for promotional and portfolio purposes.</p><p><strong>8. Confidentiality</strong> </p><p>8.1. Both parties agree to keep all project-related information confidential and not disclose it to any third party without prior written consent, except as required by law.</p><p><strong>9. Liability and Warranty</strong> </p><p>9.1. SPACEWORK will perform its services with professional care and diligence. </p><p>9.2. SPACEWORK is not liable for any project delays or costs arising from factors beyond its control, including Client-provided information or third-party dependencies. </p><p>9.3. The Client acknowledges that the deliverables are conceptual and may require further detailing and adjustment by third parties during execution.</p><p><strong>10. Termination</strong> </p><p>10.1. Either party may not terminate this Agreement, unless agreed by both parties. </p><p>10.2. Upon termination, the Client will compensate SPACEWORK for all work completed up to the termination date.</p><p><strong>11. Dispute Resolution</strong> </p><p>11.1. Any disputes arising from this Agreement will be resolved amicably through negotiations. </p><p>11.2. If negotiations fail, disputes will be subject to arbitration under the Rules of Conciliation and Arbitration at the Beirut Chamber of Commerce and Industry by three (3) Arbitrators appointed in accordance with the said rules. The said arbitrators shall have full power to open up, review and revise any decision, opinion, instruction, determination, certificate or valuation of the Engineer related to the dispute.</p><p><br></p><p><strong>12. Governing Law</strong> </p><p>This Agreement is governed by the laws of Lebanon.</p><p><strong>13. Entire Agreement</strong> </p><p>This Agreement constitutes the entire understanding between the parties and supersedes all prior agreements, understandings, or representations.</p><p><strong>14. Amendments</strong> </p><p>This Agreement may only be amended in writing and signed by both parties.</p><p><strong>IN WITNESS WHEREOF</strong>, the parties have executed this Agreement as of the date first written above.</p><p><strong>For SPACEWORK SARL</strong>                </p><p><strong>Kevin J. Gemayel</strong></p><p><em>Managing Director</em><br></p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and number = 'S00007';

