-- RINV/2025/00001
update public.invoices set narration = '<p><strong>SPACEWORK SARL</strong> (hereinafter referred to as “SPACEWORK”), a company duly registered under the laws of Lebanon, with its principal place of business located at Beirut, specializing in façade consulting, engineering, and design; </p><p><strong>1. Scope of Work</strong> </p><p>SPACEWORK agrees to provide the following services to the Client: </p><p>1.1. Façade architectural basis of design, including: </p><p class="rt-in1">a. Façade concept drawings. </p><p class="rt-in1">b. Project specifications. </p><p>1.2. Consulting and engineering services related to façade design.</p><p><strong>5. Fees and Payment</strong></p><p>5.1. The total fee for the services provided under this Agreement is mentioned above and should be settled in U.S.D Cash or USD Fresh Bank Transfer, exclusive of applicable taxes and transfer fees. </p><p>5.2. Payment milestones being Covered</p><p class="rt-in1">a. 25% upon signing this Agreement. </p><p><br></p><p>5.3. Payments must be made within 15 days of receiving an invoice, and payment delay will cause a direct delay to the project delivery.</p><p><br></p><p><strong>For SPACEWORK SARL</strong>                </p><p><strong>Kevin J. Gemayel</strong></p><p><em>Managing Director</em><br></p>'
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
   and number = 'RINV/2025/00001';

