-- @chunk

-- what landed, and whether anything is still plain text
select 'quote_templates' as what,
       count(*) filter (where note like '<%') as rich,
       count(*) filter (where note is not null and note not like '<%') as still_plain,
       count(*) filter (where note like '%<table>%') as with_a_table
  from public.quote_templates
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
union all
select 'sale_orders',
       count(*) filter (where narration like '<%'),
       count(*) filter (where narration is not null and narration not like '<%'),
       count(*) filter (where narration like '%<table>%')
  from public.sale_orders
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L')
union all
select 'invoices',
       count(*) filter (where narration like '<%'),
       count(*) filter (where narration is not null and narration not like '<%'),
       count(*) filter (where narration like '%<table>%')
  from public.invoices
 where company_id = (select id from public.companies where name = 'Space Work S.A.R.L');
